# shellcheck shell=bash
# The lb scenario: HAProxy in front of ligo1 and ligo2, TCP passthrough, so
# that client SVIDs reach ligo and clients verify ligo's own SVID
# (.specs/ligo-test-environment.md, "The load balancer lb").

# LB_PORT: the lab VM's port that publishes lb's :9443 (the web UI).
LB_PORT=9445

# lb_config: haproxy.cfg, round robin on both listeners, a TCP check per
# replica, and the stats socket for lb_check.
lb_config() {
	local port host
	cat <<CFG
# lab: generated by test/lab/lab.sh (lib/lb.sh)
global
    log /dev/log local0
    stats socket /run/haproxy/admin.sock mode 600 level admin
    # without it, HAProxy sizes itself from the container's open-file limit
    # (1048576) and the kernel kills it at LAB_LB_MEMORY
    maxconn 4096
    user haproxy
    group haproxy

defaults
    mode tcp
    log global
    option tcplog
    timeout connect 5s
    timeout client 5m
    timeout server 5m
CFG
	for port in 8443 9443; do
		printf '\nlisten ligo-%s\n    bind :%s\n    balance roundrobin\n' "$port" "$port"
		for host in ligo1 ligo2; do
			printf '    server %s %s:%s check inter 2s fall 2 rise 2\n' "$host" "$(inner_ip "$host")" "$port"
		done
	done
}

# lb_up: the container lb with HAProxy, its configuration, and the proxy
# that publishes its :9443 on the lab VM.
lb_up() {
	section "Load balancer (HAProxy)"
	inner_container lb "$LAB_LB_MEMORY"
	if ! inner_exec lb test -x /usr/sbin/haproxy; then
		inner_exec lb sh -c 'apt-get update -qq </dev/null && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq haproxy socat </dev/null >/dev/null' ||
			die "lb: cannot install haproxy"
		info "lb: $(inner_exec lb haproxy -v | head -1)"
	fi
	lb_config | inner_exec lb sh -c 'cat >/etc/haproxy/haproxy.cfg'
	inner_exec lb haproxy -c -f /etc/haproxy/haproxy.cfg >/dev/null || die "lb: haproxy.cfg is not valid"
	# a fresh start budget: the package's own start counts against it
	inner_exec lb sh -c 'systemctl reset-failed haproxy; systemctl restart haproxy'
	if ! inner config device get lb admin-ui type >/dev/null 2>&1; then
		inner config device add lb admin-ui proxy nat=true \
			listen="tcp:$(lxd_ip):$LB_PORT" connect="tcp:$(inner_ip lb):9443" >/dev/null ||
			die "cannot publish lb:9443 on the lab VM"
	fi
	env_set .lb "$(jq -n --arg ip "$(inner_ip lb)" --arg published "$(lxd_ip):$LB_PORT" '{address: $ip, published: $published}')"
	info "lb balances :8443 and :9443 over ligo1 and ligo2; the web UI through it is at https://$(lxd_ip):$LB_PORT/ui/login"
}

# lb_check: both replicas are UP behind both listeners, and each has taken
# connections on :9443, where every CLI call is a connection of its own
# (after the e2e through lb).
lb_check() {
	local stat proxy server total status
	stat="$(inner_exec lb sh -c 'echo "show stat" | socat stdio /run/haproxy/admin.sock')" || die "lb: cannot read its stats"
	# show stat is CSV: pxname,svname,...,stot (8th),...,status (18th)
	while read -r proxy server total status; do
		[[ "$status" == UP ]] || die "lb: $server behind $proxy is $status"
		[[ "$proxy" != ligo-9443 ]] || ((total > 0)) || die "lb: $server took no connection behind $proxy"
		info "lb: $server behind $proxy is UP, $total connections"
	done < <(awk -F, '$1 ~ /^ligo-/ && $2 ~ /^ligo[12]$/ {print $1, $2, $8, $18}' <<<"$stat")
}
